ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS demo_today date, ADD COLUMN IF NOT EXISTS account_status text NOT NULL DEFAULT 'active';
ALTER TABLE public.seasons ADD COLUMN IF NOT EXISTS featured_habits text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.bosses ADD COLUMN IF NOT EXISTS sponsor text, ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.habit_templates ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.challenges ADD COLUMN IF NOT EXISTS approved boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS featured boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.crews ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['seasons','bosses','habit_templates','user_habits','season_entries','checkins','daily_scores','day_extras','crews','crew_members','nudges','respects','posts','post_reactions','reports','post_hides','lift_exercises','lift_sets','detox_sessions','detox_duels','screen_time_logs','buddy_requests','buddy_links','buddy_safety_reports','season_reminders','season_trophies','boss_entries','boss_hits','bonus_points','badges','user_preferences','user_roles','challenge_squads','challenge_squad_members','time_capsules'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false',t); END LOOP; END $$;
CREATE TABLE public.admin_audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid NOT NULL,action text NOT NULL,target text,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_log TO authenticated; GRANT ALL ON public.admin_audit_log TO service_role;
ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_audit ON public.admin_audit_log FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo));
CREATE TABLE public.admin_feature_flags(key text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.admin_feature_flags TO authenticated; GRANT ALL ON public.admin_feature_flags TO service_role;
ALTER TABLE public.admin_feature_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_flags ON public.admin_feature_flags FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo));
CREATE TABLE public.admin_word_filters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),language text NOT NULL,word text NOT NULL,enabled boolean NOT NULL DEFAULT true,UNIQUE(language,word));
GRANT SELECT ON public.admin_word_filters TO authenticated; GRANT ALL ON public.admin_word_filters TO service_role;
ALTER TABLE public.admin_word_filters ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_words ON public.admin_word_filters FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo));
CREATE TABLE public.creator_referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,code text UNIQUE NOT NULL,featured boolean NOT NULL DEFAULT false,signups integer NOT NULL DEFAULT 0,is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.creator_referrals TO authenticated; GRANT ALL ON public.creator_referrals TO service_role;
ALTER TABLE public.creator_referrals ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_referrals ON public.creator_referrals FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo));
CREATE TABLE public.announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title jsonb NOT NULL,body jsonb NOT NULL,country text,language text,season_id uuid,scheduled_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.announcements TO authenticated; GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY targeted_announcement_read ON public.announcements FOR SELECT TO authenticated USING(scheduled_at<=now() AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND (country IS NULL OR country=p.country_code) AND (announcements.language IS NULL OR announcements.language=p.language) AND (NOT announcements.is_demo OR p.is_demo)) AND (season_id IS NULL OR EXISTS(SELECT 1 FROM public.season_entries e WHERE e.user_id=auth.uid() AND e.season_id=announcements.season_id)));
CREATE TABLE public.announcement_receipts(announcement_id uuid REFERENCES public.announcements(id) ON DELETE CASCADE,user_id uuid NOT NULL,read_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false,PRIMARY KEY(announcement_id,user_id));
GRANT SELECT,INSERT ON public.announcement_receipts TO authenticated; GRANT ALL ON public.announcement_receipts TO service_role;
ALTER TABLE public.announcement_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_announcement_receipts ON public.announcement_receipts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.announcements WHERE id=announcement_id));
CREATE TABLE public.admin_suspicious_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,kind text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',day date,status text NOT NULL DEFAULT 'open',is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_suspicious_activity TO authenticated; GRANT ALL ON public.admin_suspicious_activity TO service_role;
ALTER TABLE public.admin_suspicious_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_suspicious ON public.admin_suspicious_activity FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo));
CREATE TABLE public.activity_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,kind text NOT NULL,device_key text,network_key text,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.activity_events TO service_role;
ALTER TABLE public.activity_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.proof_fingerprints(path text PRIMARY KEY,user_id uuid NOT NULL,fingerprint text NOT NULL,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.proof_fingerprints TO service_role;
ALTER TABLE public.proof_fingerprints ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.demo_login_limits(key text NOT NULL,window_start timestamptz NOT NULL,hits integer NOT NULL DEFAULT 0,PRIMARY KEY(key,window_start));
GRANT ALL ON public.demo_login_limits TO service_role;
ALTER TABLE public.demo_login_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public._require_admin() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND is_admin AND NOT is_demo AND account_status='active') THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN auth.uid(); END $$;
REVOKE ALL ON FUNCTION public._require_admin() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._admin_audit(_action text,_target text DEFAULT NULL,_payload jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO admin_audit_log(admin_id,action,target,payload) VALUES(public._require_admin(),_action,_target,_payload); END $$;
REVOKE ALL ON FUNCTION public._admin_audit(text,text,jsonb) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.admin_authorized() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public._require_admin(); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.admin_authorized() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_authorized() TO authenticated;
CREATE FUNCTION public.bootstrap_super_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='med.adem.1999@gmail.com' THEN UPDATE public.profiles SET is_admin=true WHERE id=NEW.id; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT(user_id,role) DO NOTHING; INSERT INTO public.admin_audit_log(admin_id,action,target,payload) VALUES(NEW.id,'bootstrap_admin',NEW.id::text,'{}'); END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_lezgo_bootstrap_admin AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.bootstrap_super_admin();
REVOKE ALL ON FUNCTION public.bootstrap_super_admin() FROM PUBLIC,anon,authenticated;
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin' FROM public.profiles WHERE is_admin ON CONFLICT(user_id,role) DO NOTHING;
CREATE OR REPLACE FUNCTION public._local_today(_user_id uuid) RETURNS date LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p.is_demo AND p.demo_today IS NOT NULL THEN p.demo_today ELSE (now() AT TIME ZONE p.timezone)::date END FROM (SELECT coalesce((SELECT timezone FROM profiles WHERE id=_user_id),'Africa/Tunis') timezone,coalesce((SELECT is_demo FROM profiles WHERE id=_user_id),false) is_demo,(SELECT demo_today FROM profiles WHERE id=_user_id) demo_today)p $$;
CREATE OR REPLACE FUNCTION public._check_day_window(_user_id uuid,_day date) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tz text; ts timestamp; BEGIN SELECT timezone INTO tz FROM profiles WHERE id=_user_id; ts:=now() AT TIME ZONE coalesce(tz,'Africa/Tunis'); IF _day=public._local_today(_user_id) OR (_day=public._local_today(_user_id)-1 AND ts::time<time '03:00') THEN RETURN; END IF; RAISE EXCEPTION 'day_closed'; END $$;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.recompute_day(uuid,uuid,date)'::regprocedure) INTO f; f:=replace(f,'today:=(now() AT TIME ZONE tz)::date','today:=public._local_today(_user_id)'); EXECUTE f; END $$;
CREATE FUNCTION public.guard_account_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor profiles; j jsonb; rid uuid; parent_demo boolean; parent_post uuid; BEGIN IF auth.uid() IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; SELECT * INTO actor FROM profiles WHERE id=auth.uid(); IF actor.account_status<>'active' THEN RAISE EXCEPTION 'account_blocked'; END IF; IF TG_OP='DELETE' THEN j:=to_jsonb(OLD); ELSE j:=to_jsonb(NEW); END IF;
IF actor.is_demo THEN
 IF TG_TABLE_NAME='profiles' AND TG_OP='DELETE' THEN RAISE EXCEPTION 'demo_protected'; END IF;
 IF TG_OP<>'INSERT' AND coalesce((j->>'is_demo')::boolean,false)=false THEN RAISE EXCEPTION 'demo_only'; END IF;
 FOREACH rid IN ARRAY ARRAY[(j->>'to_user')::uuid,(j->>'from_user')::uuid,(j->>'reporter')::uuid] LOOP IF rid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM profiles WHERE id=rid AND is_demo) THEN RAISE EXCEPTION 'demo_only'; END IF; END LOOP;
 IF j ? 'post_id' THEN SELECT is_demo INTO parent_demo FROM posts WHERE id=(j->>'post_id')::uuid; IF parent_demo IS DISTINCT FROM true THEN RAISE EXCEPTION 'demo_only'; END IF; END IF;
 IF TG_TABLE_NAME='user_preferences' AND j->>'active_challenge_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM challenges WHERE id=(j->>'active_challenge_id')::uuid AND is_demo) THEN RAISE EXCEPTION 'demo_only'; END IF;
 IF TG_TABLE_NAME IN('challenges','crews') THEN RAISE EXCEPTION 'demo_readonly'; END IF;
 IF TG_TABLE_NAME='posts' THEN NEW:=jsonb_populate_record(NEW,jsonb_build_object('is_demo',true)); ELSIF TG_OP<>'DELETE' THEN NEW:=jsonb_populate_record(NEW,jsonb_build_object('is_demo',true)); END IF;
END IF;
IF TG_TABLE_NAME='profiles' AND TG_OP='DELETE' AND coalesce((j->>'is_demo')::boolean,false) THEN RAISE EXCEPTION 'demo_protected'; END IF;
IF TG_OP='DELETE' THEN RETURN OLD; END IF;
IF NOT actor.is_demo AND TG_TABLE_NAME IN('user_habits','season_entries','crews','challenges','posts') AND coalesce((j->>'is_demo')::boolean,false) AND NOT actor.is_admin THEN RAISE EXCEPTION 'demo_only'; END IF;
IF TG_TABLE_NAME='posts' THEN SELECT language INTO j FROM profiles WHERE id=NEW.user_id; END IF;
RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','user_habits','checkins','day_extras','daily_scores','season_entries','crews','crew_members','nudges','respects','posts','post_reactions','reports','post_hides','lift_sets','detox_sessions','detox_duels','screen_time_logs','buddy_requests','buddy_safety_reports','user_preferences','challenges','boss_hits','boss_entries','bonus_points','badges','season_reminders','season_trophies','time_capsules','announcement_receipts'] LOOP EXECUTE format('CREATE TRIGGER account_content_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_account_content()',t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.guard_account_content() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.moderate_post_on_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.body ~* '(https?://|www\.)' AND coalesce((SELECT enabled FROM admin_feature_flags WHERE key='auto_flag_links'),true) OR EXISTS(SELECT 1 FROM admin_word_filters f JOIN profiles p ON p.id=NEW.user_id WHERE f.enabled AND f.language=p.language AND position(lower(f.word) IN lower(NEW.body))>0) THEN NEW.hidden:=true; INSERT INTO admin_suspicious_activity(user_id,kind,detail,day,is_demo) VALUES(NEW.user_id,'filtered_post',jsonb_build_object('post_id',NEW.id),NEW.day,NEW.is_demo); END IF; RETURN NEW; END $$;
CREATE TRIGGER post_word_filter BEFORE INSERT OR UPDATE OF body ON public.posts FOR EACH ROW EXECUTE FUNCTION public.moderate_post_on_write();
REVOKE ALL ON FUNCTION public.moderate_post_on_write() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.track_checkin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n int; BEGIN INSERT INTO activity_events(user_id,kind,is_demo) VALUES(NEW.user_id,'checkin',NEW.is_demo); SELECT count(*) INTO n FROM activity_events WHERE user_id=NEW.user_id AND kind='checkin' AND created_at>now()-interval '1 minute'; IF n=21 THEN INSERT INTO admin_suspicious_activity(user_id,kind,detail,day,is_demo) VALUES(NEW.user_id,'rapid_checkins',jsonb_build_object('count',n),NEW.day,NEW.is_demo); END IF; IF auth.uid()=NEW.user_id AND NEW.day<public._local_today(NEW.user_id) AND (now() AT TIME ZONE (SELECT timezone FROM profiles WHERE id=NEW.user_id))::time>=time '03:00' THEN INSERT INTO admin_suspicious_activity(user_id,kind,day,is_demo) VALUES(NEW.user_id,'late_edit',NEW.day,NEW.is_demo); END IF; RETURN NEW; END $$;
CREATE TRIGGER checkin_activity AFTER INSERT OR UPDATE ON public.checkins FOR EACH ROW EXECUTE FUNCTION public.track_checkin_activity();
REVOKE ALL ON FUNCTION public.track_checkin_activity() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.track_lift_jump() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous numeric; BEGIN SELECT weight*reps INTO previous FROM lift_sets WHERE user_id=NEW.user_id AND exercise_id=NEW.exercise_id AND day<NEW.day ORDER BY day DESC LIMIT 1; IF previous>0 AND NEW.weight*NEW.reps>previous*1.5 THEN INSERT INTO admin_suspicious_activity(user_id,kind,detail,day,is_demo) VALUES(NEW.user_id,'lift_jump',jsonb_build_object('previous',previous,'current',NEW.weight*NEW.reps),NEW.day,NEW.is_demo); END IF; RETURN NEW; END $$;
CREATE TRIGGER lift_jump_check AFTER INSERT OR UPDATE ON public.lift_sets FOR EACH ROW EXECUTE FUNCTION public.track_lift_jump();
REVOKE ALL ON FUNCTION public.track_lift_jump() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.claim_demo_login(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w timestamptz:=date_trunc('minute',now()); n int; BEGIN INSERT INTO demo_login_limits(key,window_start,hits) VALUES(_key,w,1) ON CONFLICT(key,window_start) DO UPDATE SET hits=demo_login_limits.hits+1 RETURNING hits INTO n; IF n>10 THEN RETURN false; END IF; INSERT INTO demo_login_limits(key,window_start,hits) VALUES('global',w,1) ON CONFLICT(key,window_start) DO UPDATE SET hits=demo_login_limits.hits+1 RETURNING hits INTO n; RETURN n<=60; END $$;
REVOKE ALL ON FUNCTION public.claim_demo_login(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_demo_login(text) TO service_role;
CREATE FUNCTION public.app_feature_flags() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(key,enabled),'{}') FROM admin_feature_flags WHERE key IN('buddies','duels','bosses','creator_challenges','apple_signin','push') $$;
REVOKE ALL ON FUNCTION public.app_feature_flags() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.app_feature_flags() TO anon,authenticated;
CREATE FUNCTION public.admin_action(_action text,_target uuid DEFAULT NULL,_payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; tbl text; allowed text[]; cols text; pairs text; k text; result_id uuid; r record; BEGIN uid:=public._require_admin(); IF octet_length(_payload::text)>32000 THEN RAISE EXCEPTION 'invalid_payload'; END IF;
IF _action='role' THEN IF _payload->>'role' NOT IN('user','creator','admin') OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=_target AND NOT is_demo) THEN RAISE EXCEPTION 'invalid_role'; END IF; IF _target=uid AND _payload->>'role'<>'admin' THEN RAISE EXCEPTION 'self_protected'; END IF; DELETE FROM user_roles WHERE user_id=_target AND role IN('user','creator','admin'); INSERT INTO user_roles(user_id,role) VALUES(_target,_payload->>'role'); UPDATE profiles SET is_admin=(_payload->>'role'='admin') WHERE id=_target;
ELSIF _action IN('ban','unban','delete_user') THEN IF _target=uid OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=_target AND NOT is_admin AND NOT is_demo) THEN RAISE EXCEPTION 'user_protected'; END IF; UPDATE profiles SET account_status=CASE _action WHEN 'unban' THEN 'active' WHEN 'delete_user' THEN 'deleted' ELSE 'banned' END WHERE id=_target;
ELSIF _action IN('reset_day','reset_streak') THEN IF length(trim(coalesce(_payload->>'reason','')))<3 THEN RAISE EXCEPTION 'reason_required'; END IF; IF _action='reset_day' THEN DELETE FROM checkins WHERE user_id=_target AND day=(_payload->>'day')::date; DELETE FROM day_extras WHERE user_id=_target AND day=(_payload->>'day')::date; ELSE DELETE FROM checkins WHERE user_id=_target AND day=public._local_today(_target)-1; DELETE FROM day_extras WHERE user_id=_target AND day=public._local_today(_target)-1; END IF; FOR r IN SELECT season_id FROM season_entries WHERE user_id=_target LOOP PERFORM public._recompute_with_crew(_target,r.season_id,public._local_today(_target)); END LOOP;
ELSIF _action IN('keep_post','remove_post') THEN UPDATE posts SET hidden=(_action='remove_post') WHERE id=_target; DELETE FROM reports WHERE post_id=_target; UPDATE admin_suspicious_activity SET status='resolved' WHERE detail->>'post_id'=_target::text;
ELSIF _action='review' THEN UPDATE admin_suspicious_activity SET status='reviewed' WHERE id=_target;
ELSIF _action='flag' THEN IF _payload->>'key' NOT IN('buddies','duels','bosses','creator_challenges','apple_signin','push','auto_flag_links') THEN RAISE EXCEPTION 'invalid_flag'; END IF; INSERT INTO admin_feature_flags(key,enabled) VALUES(_payload->>'key',(_payload->>'enabled')::boolean) ON CONFLICT(key) DO UPDATE SET enabled=excluded.enabled;
ELSIF _action='word_filter' THEN IF _payload->>'language' NOT IN('en','fr','ar','aeb') OR char_length(trim(_payload->>'word')) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_filter'; END IF; INSERT INTO admin_word_filters(language,word,enabled) VALUES(_payload->>'language',trim(_payload->>'word'),coalesce((_payload->>'enabled')::boolean,true)) ON CONFLICT(language,word) DO UPDATE SET enabled=excluded.enabled;
ELSIF _action='delete_filter' THEN DELETE FROM admin_word_filters WHERE id=_target;
ELSIF _action='approve_challenge' THEN UPDATE challenges SET approved=true WHERE id=_target;
ELSIF _action='feature_challenge' THEN UPDATE challenges SET featured=coalesce((_payload->>'featured')::boolean,true) WHERE id=_target;
ELSIF _action='feature_creator' THEN UPDATE creator_referrals SET featured=coalesce((_payload->>'featured')::boolean,true) WHERE id=_target;
ELSIF _action IN('disband_crew','disband_challenge') THEN IF _action='disband_crew' THEN UPDATE crews SET archived=true,is_public=false WHERE id=_target; DELETE FROM crew_members WHERE crew_id=_target; ELSE UPDATE challenges SET archived=true,public_board=false WHERE id=_target; UPDATE crews SET archived=true,is_public=false WHERE id=(SELECT crew_id FROM challenges WHERE id=_target); DELETE FROM crew_members WHERE crew_id=(SELECT crew_id FROM challenges WHERE id=_target); UPDATE seasons SET status='ended',archived=true WHERE id=(SELECT season_id FROM challenges WHERE id=_target); END IF;
ELSIF _action IN('archive_season','archive_boss','archive_habit') THEN tbl:=CASE _action WHEN 'archive_season' THEN 'seasons' WHEN 'archive_boss' THEN 'bosses' ELSE 'habit_templates' END; EXECUTE format('UPDATE public.%I SET archived=true WHERE id=$1',tbl) USING _target;
ELSIF _action IN('save_season','save_boss','save_habit','broadcast','save_referral') THEN
 tbl:=CASE _action WHEN 'save_season' THEN 'seasons' WHEN 'save_boss' THEN 'bosses' WHEN 'save_habit' THEN 'habit_templates' WHEN 'broadcast' THEN 'announcements' ELSE 'creator_referrals' END;
 allowed:=CASE _action WHEN 'save_season' THEN ARRAY['slug','name','starts_on','ends_on','status','theme_color','featured_habits'] WHEN 'save_boss' THEN ARRAY['season_id','week_no','slug','name','rule','metric','exercise_key','levels','starts_at','ends_at','color','sponsor'] WHEN 'save_habit' THEN ARRAY['key','category','name','description','icon','kind','default_target','unit','is_faith','sort','color'] WHEN 'broadcast' THEN ARRAY['title','body','country','language','season_id','scheduled_at'] ELSE ARRAY['user_id','code','featured'] END;
 FOR k IN SELECT jsonb_object_keys(_payload) LOOP IF NOT(k=ANY(allowed)) THEN RAISE EXCEPTION 'invalid_field'; END IF; END LOOP;
 FOREACH k IN ARRAY ARRAY['name','rule','description','title','body'] LOOP IF _payload ? k THEN IF jsonb_typeof(_payload->k)<>'object' OR EXISTS(SELECT 1 FROM unnest(ARRAY['en','fr','ar','aeb']) l WHERE length(trim(coalesce(_payload->k->>l,'')))=0) THEN RAISE EXCEPTION 'four_languages_required'; END IF; END IF; END LOOP;
 IF _action='save_season' AND (_payload->>'ends_on')::date<(_payload->>'starts_on')::date THEN RAISE EXCEPTION 'invalid_dates'; END IF;
 IF _action='save_boss' AND (jsonb_array_length(_payload->'levels')<>3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_payload->'levels') lv WHERE (lv->>'target')::numeric<=0 OR (lv->>'bonus')::integer<0)) THEN RAISE EXCEPTION 'invalid_levels'; END IF;
 SELECT string_agg(format('%I',key),','),string_agg(format('%I=x.%I',key,key),',') INTO cols,pairs FROM jsonb_object_keys(_payload) key;
 IF cols IS NULL THEN RAISE EXCEPTION 'invalid_payload'; END IF;
 IF _target IS NULL THEN EXECUTE format('INSERT INTO public.%I(%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) x RETURNING id',tbl,cols,cols,tbl) INTO result_id USING _payload; ELSE EXECUTE format('UPDATE public.%I AS t SET %s FROM jsonb_populate_record(NULL::public.%I,$1) x WHERE t.id=$2 RETURNING t.id',tbl,pairs,tbl) INTO result_id USING _payload,_target; END IF;
ELSE RAISE EXCEPTION 'invalid_action'; END IF;
PERFORM public._admin_audit(_action,coalesce(_target,result_id)::text,_payload); RETURN jsonb_build_object('id',coalesce(result_id,_target),'ok',true); END $$;
REVOKE ALL ON FUNCTION public.admin_action(text,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_action(text,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.admin_security_presence(_device text,_network text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n int; demo boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; SELECT is_demo INTO demo FROM profiles WHERE id=auth.uid(); IF NOT EXISTS(SELECT 1 FROM activity_events WHERE user_id=auth.uid() AND kind='presence' AND created_at>now()-interval '1 hour') THEN INSERT INTO activity_events(user_id,kind,device_key,network_key,is_demo) VALUES(auth.uid(),'presence',_device,_network,demo); SELECT count(DISTINCT user_id) INTO n FROM activity_events WHERE kind='presence' AND created_at>now()-interval '1 day' AND (device_key=_device OR network_key=_network); IF n>=4 THEN INSERT INTO admin_suspicious_activity(user_id,kind,detail,is_demo) VALUES(auth.uid(),'multiple_accounts',jsonb_build_object('accounts',n),demo); END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_security_presence(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_security_presence(text,text) TO authenticated;
CREATE FUNCTION public.register_proof_fingerprint(_path text,_fingerprint text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; BEGIN u:=auth.uid(); IF u IS NULL OR split_part(_path,'/',1)<>u::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='proofs' AND name=_path) THEN RAISE EXCEPTION 'forbidden'; END IF; IF EXISTS(SELECT 1 FROM proof_fingerprints WHERE fingerprint=_fingerprint AND user_id<>u) THEN INSERT INTO admin_suspicious_activity(user_id,kind,detail,is_demo) SELECT u,'duplicate_proof',jsonb_build_object('path',_path),is_demo FROM profiles WHERE id=u; END IF; INSERT INTO proof_fingerprints(path,user_id,fingerprint,is_demo) SELECT _path,u,_fingerprint,is_demo FROM profiles WHERE id=u ON CONFLICT(path) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.register_proof_fingerprint(text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.register_proof_fingerprint(text,text) TO service_role;
COMMENT ON FUNCTION public.register_proof_fingerprint(text,text) IS 'Only the authenticated server wrapper may submit hashes computed from saved image bytes.';